import{_ as o}from"./chunks/position_fixed.t2m3lWVy.js";import{_ as l}from"./chunks/acceptance_radius_mission.Dv7TEdpG.js";import{_ as n,C as _,o as s,c as m,al as t,j as e,a as i,E as h}from"./chunks/framework.7vp1BMOE.js";const V=JSON.parse('{"title":"Режим місії (Мультикоптер)","description":"","frontmatter":{},"headers":[],"relativePath":"uk/flight_modes_mc/mission.md","filePath":"uk/flight_modes_mc/mission.md"}'),d={name:"uk/flight_modes_mc/mission.md"},c={tabindex:"0"};function A(f,a,M,p,g,u){const r=_("Badge");return s(),m("div",null,[a[7]||(a[7]=t('<h1 id="режим-місіі-мультикоптер" tabindex="-1">Режим місії (Мультикоптер) <a class="header-anchor" href="#режим-місіі-мультикоптер" aria-label="Permalink to &quot;Режим місії (Мультикоптер)&quot;">​</a></h1><img src="'+o+'" title="Global position fix required (e.g. GPS)" width="30px"><p><em>Режим місії</em> змушує транспортний засіб виконувати передбачений автономний <a href="./../flying/missions">план місії</a> (план польоту), який був завантажений до керуючого пристрою польоту. Зазвичай місія створюється та завантажується за допомогою програми для керування наземною станцією (GCS), такої як <a href="https://docs.qgroundcontrol.com/master/en/" target="_blank" rel="noreferrer">QGroundControl</a> (QGC).</p><div class="info custom-block"><p class="custom-block-title">INFO</p><ul><li>Цей режим потребує глобальної оцінки 3D-позиції (з GPS або виведеної з <a href="./../ros/external_position_estimation#enabling-auto-modes-with-a-local-position">локальної позиції</a>).</li><li>Транспортний засіб повинен бути озброєний перед тим, як цей режим може бути активований.</li><li>Цей режим є автоматичним - для керування автомобілем не потрібно втручання користувача.</li><li>Перемикачі керування RC можуть використовуватися для зміни режимів польоту на будь-якому транспортному засобі.</li><li>Stick movement will <a href="#MAN_OVERRIDE_SPD">by default</a> change the vehicle to <a href="./../flight_modes_mc/position">Position mode</a> unless prevented by the active failsafe state. This is true for multicopters and VTOL in hover.</li><li>The yaw stick can optionally nudge vehicle heading during the mission without changing mode (see <a href="#MPC_AUTO_NUDGING">MPC_AUTO_NUDGING</a>).</li></ul></div><h3 id="mode-requirements" tabindex="-1">Mode Requirements <a class="header-anchor" href="#mode-requirements" aria-label="Permalink to &quot;Mode Requirements&quot;">​</a></h3><p>The following requirements must be met to arm in this mode, or to switch to this mode when it is armed.</p><ul><li><a href="./../flight_modes/mode_requirements#mode_req_angular_velocity"><code>mode_req_angular_velocity</code></a> — Angular velocity</li><li><a href="./../flight_modes/mode_requirements#mode_req_attitude"><code>mode_req_attitude</code></a> — Attitude/pose</li><li><a href="./../flight_modes/mode_requirements#mode_req_global_position"><code>mode_req_global_position</code></a> — Position measurement updates in a global coordinate frame</li><li><a href="./../flight_modes/mode_requirements#mode_req_local_alt"><code>mode_req_local_alt</code></a> — Local altitude relative to EKF2 origin (&#39;0&#39;) position</li><li><a href="./../flight_modes/mode_requirements#mode_req_local_position"><code>mode_req_local_position</code></a> — Position relative to EKF2 origin (&#39;0&#39;) point</li><li><a href="./../flight_modes/mode_requirements#mode_req_mission"><code>mode_req_mission</code></a> — Valid mission in autopilot&#39;s storage</li><li><a href="./../flight_modes/mode_requirements#mode_req_wind_and_flight_time_compliance"><code>mode_req_wind_and_flight_time_compliance</code></a> — Safety compliance limits on wind and flight time.</li></ul><h2 id="опис" tabindex="-1">Опис <a class="header-anchor" href="#опис" aria-label="Permalink to &quot;Опис&quot;">​</a></h2><p>Місії зазвичай створюються в земній контрольній станції (наприклад, <a href="https://docs.qgroundcontrol.com/master/en/qgc-user-guide/plan_view/plan_view.html" target="_blank" rel="noreferrer">QGroundControl</a>) та завантажуються перед запуском. They may also be created by a MAVLink API such as <a href="./../robotics/mavsdk">MAVSDK</a>, and/or uploaded in flight.</p><p>Індивідуальні <a href="#mission-commands">команди місії</a> обробляються таким чином, який є відповідним для характеристик багтороторного польоту (наприклад, обертання виконується у вигляді <em>залишання на місці</em>).</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Місії завантажуються на SD-карту, яку потрібно вставити <strong>перед</strong> запуском автопілота.</p></div><p>На високому рівні всі типи транспортних засобів ведуть себе однаково, коли ввімкнено режим МІСІЯ:</p><ol><li><p>Якщо місія не збережена, або якщо PX4 завершив виконання всіх команд місії, або якщо <a href="#mission-feasibility-checks">місія не є можливою</a>:</p><ul><li>Якщо літає транспортний засіб, він буде утримувати.</li><li>Якщо посадять транспортний засіб, він буде &quot;чекати&quot;.</li></ul></li><li><p>Якщо місія збережена, а PX4 летить, вона виконає <a href="./../flying/missions">місію / план польоту</a> з поточного кроку.</p><ul><li>Пункт <code>TAKEOFF</code> трактується як звичайна точка місії.</li></ul></li><li><p>Якщо місія збережена і PX4 приземлився:</p><ul><li>PX4 виконає <a href="./../flying/missions">місію/план польоту</a>.</li><li>Якщо місія не має пункту <code>TAKEOFF</code>, то PX4 підніме транспортний засіб на мінімальну висоту перед виконанням решти польотного плану з поточного кроку.</li></ul></li><li><p>Якщо жодне завдання не збережено, або якщо PX4 завершив виконання всіх команд місії:</p><ul><li>Якщо літає транспортний засіб, він буде утримувати.</li><li>Якщо посадять транспортний засіб, він буде &quot;чекати&quot;.</li></ul></li><li><p>Ви можете вручну змінити поточну команду місії, вибравши її в <em>QGroundControl</em>.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Якщо у вас є команда <em>Перейти до елементу</em> в місії, переміщення до іншого елементу <strong>не</strong> скине лічильник циклу. Однією з наслідків є те, що якщо ви зміните поточну команду місії на 1, це не призведе до &quot;повного перезапуску&quot; місії.</p></div></li></ol><p>:::</p><ol start="6"><li><p>Місія скине тільки тоді, коли транспортний засіб буде роззброєний або коли буде завантажена нова місія.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Щоб автоматично роззброїти транспортний засіб після посадки, у <em>QGroundControl</em> перейдіть до <a href="https://docs.qgroundcontrol.com/master/en/qgc-user-guide/setup_view/safety.html" target="_blank" rel="noreferrer">Налаштування Транспортного Засобу &gt; Безпека</a>, перейдіть до <em>Налаштувань Режиму Посадки</em> та позначте прапорець <em>Роззброювати після</em>. Введіть час очікування після посадки перед відброюванням транспортного засобу.</p></div></li></ol><p>:::</p><p>Місії можна призупинити, переключившись з режиму місії на будь-який інший режим (наприклад, <a href="./../flight_modes_mc/hold">режим утримання</a> або <a href="./../flight_modes_mc/position">режим позиціонування</a>), і продовжити, переключившись назад в режим місії. Якщо транспортний засіб не захоплював зображення, коли він був призупинений, під час відновлення він рухатиметься зі своєї <em>поточної позиції</em> до тієї ж точки шляху, до якої він спочатку рухався. Якщо транспортний засіб захоплював зображення (має елементи спуску камери), він замість цього рухатиметься зі своєї поточної позиції до останньої точки шляху, якою він проїхав (перед зупинкою), а потім пройде свій шлях з тією самою швидкістю та з такою самою поведінкою спуску камери. Це забезпечує, що планований шлях зафіксований під час місій з опитування/камери. A mission can be uploaded while the vehicle is paused, in which case the current active mission item is set to 1.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Коли місію призупинено під час спрацювання камери на транспортному засобі, PX4 встановлює поточний активний пункт місії на попередню точку маршруту, так що при відновленні місії транспортний засіб буде повторювати свій останній етап місії. Крім того, PX4 зберігає останні застосовані пункти місії для налаштування швидкості та спуску камери (з вже покритого плану місії) та знову застосовує ці налаштування при відновленні місії.</p></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Переконайтеся, що палиця регулювання газу не дорівнює нулю перед переключенням в будь-який режим RC (інакше транспортний засіб розбився). Ми рекомендуємо вам вирівнювати ручки керування перед переходом до будь-якого іншого режиму.</p></div><p>Для отримання додаткової інформації про планування місії, див:</p><ul><li><a href="./../flying/missions">Планування місій</a></li><li><a href="https://docs.qgroundcontrol.com/master/en/qgc-user-guide/plan_view/plan_view.html" target="_blank" rel="noreferrer">План Перегляду</a> (<em>Посібник користувача QGroundControl</em>)</li></ul><h2 id="перевірки-можливостеи-місіі" tabindex="-1">Перевірки можливостей місії <a class="header-anchor" href="#перевірки-можливостеи-місіі" aria-label="Permalink to &quot;Перевірки можливостей місії&quot;">​</a></h2><p>PX4 runs some basic sanity checks to determine if a mission is feasible when it is uploaded and before executing a mission. If any of the checks fail, the user is notified and it is not possible to start the mission (the vehicle will switch to <a href="./../flight_modes_mc/hold">Hold mode</a> instead of Mission mode).</p><p>Підмножина найважливіших перевірок перерахована нижче:</p><ul><li>Будь-який елемент місії конфліктує з планом або безпечним геозахистом</li><li>Відсутній пункт зльоту та/або посадки, коли вони налаштовані як вимога (<a href="#MIS_TKO_LAND_REQ">MIS_TKO_LAND_REQ</a>)</li></ul><p>Additionally there is a check if the first waypoint is too far from the Home position (<a href="#MIS_DIST_1WP">MIS_DIST_1WP</a>). The user is notified should the check fail, but it has no effect on the validity of a mission plan, meaning that the mission can still be started even if the distance is too high.</p><h2 id="qgroundcontrol-підтримка" tabindex="-1">QGroundControl Підтримка <a class="header-anchor" href="#qgroundcontrol-підтримка" aria-label="Permalink to &quot;QGroundControl Підтримка&quot;">​</a></h2><p><em>QGroundControl</em> надає додаткову підтримку обробки місій на рівні GCS (на додачу до того, що надає контролер польоту).</p><p>Для додаткової інформації дивіться:</p><ul><li><a href="https://docs.qgroundcontrol.com/Stable_V4.3/en/qgc-user-guide/releases/stable_v3.2_long.html#remove-mission-after-vehicle-lands" target="_blank" rel="noreferrer">Remove mission after vehicle lands</a></li><li><a href="https://docs.qgroundcontrol.com/Stable_V4.3/en/qgc-user-guide/releases/stable_v3.2_long.html#resume-mission" target="_blank" rel="noreferrer">Resume mission after Return mode</a></li></ul><h2 id="параметри-місіі" tabindex="-1">Параметри місії <a class="header-anchor" href="#параметри-місіі" aria-label="Permalink to &quot;Параметри місії&quot;">​</a></h2><p>Поведінка місій залежить від ряду параметрів, більшість з яких задокументовані в <a href="./../advanced_config/parameter_reference#mission">Довідник параметрів &gt; Місія</a>. Дуже маленька підмножина наведені нижче.</p><p>Загальні параметри:</p>',33)),e("table",c,[a[6]||(a[6]=e("thead",null,[e("tr",null,[e("th",null,"Parameter"),e("th",null,"Опис")])],-1)),e("tbody",null,[a[4]||(a[4]=e("tr",null,[e("td",null,[e("a",{id:"NAV_RCL_ACT"}),e("a",{href:"./../advanced_config/parameter_reference#NAV_RCL_ACT"},"NAV_RCL_ACT")]),e("td",null,"Режим аварійного відновлення зв'язку RC (що робить транспортний засіб, якщо втрачає зв'язок RC) - наприклад, увійти в режим утримання, режим повернення, завершити тощо.")],-1)),e("tr",null,[a[3]||(a[3]=e("td",null,[e("a",{id:"MAN_OVERRIDE_SPD"}),e("a",{href:"./../advanced_config/parameter_reference#MAN_OVERRIDE_SPD"},"MAN_OVERRIDE_SPD")],-1)),e("td",null,[a[0]||(a[0]=i("Speed (normalized stick travel per second) above which moving the sticks controlling a multicopter (or VTOL in hover) gives control back to the pilot by switching to ",-1)),a[1]||(a[1]=e("a",{href:"./../flight_modes_mc/position"},"Position mode",-1)),a[2]||(a[2]=i(" (or Altitude mode if position is unavailable). At the default value of 1 a half-stick movement in ~0.5 s triggers it; lower is more sensitive. A stick held statically has zero speed and will not trigger. Set to -1 to disable. ",-1)),h(r,{type:"tip",text:"PX4 v1.18"})])]),a[5]||(a[5]=e("tr",null,[e("td",null,[e("a",{id:"MPC_AUTO_NUDGING"}),e("a",{href:"./../advanced_config/parameter_reference#MPC_AUTO_NUDGING"},"MPC_AUTO_NUDGING")]),e("td",null,[i("Bitmask enabling stick nudging in Auto modes (multicopter). Bit 0 (yaw nudging) lets the yaw stick nudge heading without switching modes; the heading is held when the stick is released. Switching flight mode (e.g. to Hold and back) clears the held heading and returns yaw to the mode default. Requires stick override to be disabled ("),e("a",{href:"#MAN_OVERRIDE_SPD"},"MAN_OVERRIDE_SPD"),i(" = -1).")])],-1))])]),a[8]||(a[8]=t('<p>Параметри, пов&#39;язані з <a href="#mission-feasibility-checks">перевірками можливостей місії</a>:</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Опис</th></tr></thead><tbody><tr><td><a id="MIS_DIST_1WP"></a><a href="./../advanced_config/parameter_reference#MIS_DIST_1WP">MIS_DIST_1WP</a></td><td>There is a warning message if the distance of the first waypoint to Home is more than this value. Вимкнено, якщо значення дорівнює 0 або менше.</td></tr><tr><td><a id="FW_LND_ANG"></a><a href="./../advanced_config/parameter_reference#FW_LND_ANG">FW_LND_ANG</a></td><td>Максимальний кут нахилу підйому.</td></tr><tr><td><a id="MIS_TKO_LAND_REQ"></a><a href="./../advanced_config/parameter_reference#MIS_TKO_LAND_REQ">MIS_TKO_LAND_REQ</a></td><td>Sets whether mission <em>requires</em> takeoff and/or landing items. No requirement by default for multicopter.</td></tr></tbody></table><h2 id="mission_commands" tabindex="-1">Mission Commands <a class="header-anchor" href="#mission_commands" aria-label="Permalink to &quot;Mission Commands {#mission_commands}&quot;">​</a></h2><p>PX4 &quot;приймає&quot; наступні команди місії MAVLink у режимі Місії (з деякими <em>попередженнями</em>, які наведені після списку). Якщо не вказано інше, реалізація відповідає визначенню у специфікації MAVLink.</p><p>Предмети місії:</p><ul><li><a href="https://mavlink.io/en/messages/common.html#MAV_CMD_NAV_WAYPOINT" target="_blank" rel="noreferrer">MAV_CMD_NAV_WAYPOINT</a><ul><li><em>Param3</em> (проліт) ігнорується. Flythrough завжди ввімкнено, якщо <em>param 1</em> (time_inside) &gt; 0.</li></ul></li><li><a href="https://mavlink.io/en/messages/common.html#MAV_CMD_NAV_LOITER_UNLIM" target="_blank" rel="noreferrer">MAV_CMD_NAV_LOITER_UNLIM</a></li><li><a href="https://mavlink.io/en/messages/common.html#MAV_CMD_NAV_LOITER_TIME" target="_blank" rel="noreferrer">MAV_CMD_NAV_LOITER_TIME</a></li><li><a href="https://mavlink.io/en/messages/common.html#MAV_CMD_NAV_LAND" target="_blank" rel="noreferrer">MAV_CMD_NAV_LAND</a></li><li><a href="https://mavlink.io/en/messages/common.html#MAV_CMD_NAV_TAKEOFF" target="_blank" rel="noreferrer">MAV_CMD_NAV_TAKEOFF</a></li><li><a href="https://mavlink.io/en/messages/common.html#MAV_CMD_NAV_LOITER_TO_ALT" target="_blank" rel="noreferrer">MAV_CMD_NAV_LOITER_TO_ALT</a></li><li><a href="https://mavlink.io/en/messages/common.html#MAV_CMD_DO_JUMP" target="_blank" rel="noreferrer">MAV_CMD_DO_JUMP</a></li><li><a href="https://mavlink.io/en/messages/common.html#MAV_CMD_NAV_ROI" target="_blank" rel="noreferrer">MAV_CMD_NAV_ROI</a></li><li><a href="https://mavlink.io/en/messages/common.html#MAV_CMD_DO_SET_ROI" target="_blank" rel="noreferrer">MAV_CMD_DO_SET_ROI</a></li><li><a href="https://mavlink.io/en/messages/common.html#MAV_CMD_DO_SET_ROI_LOCATION" target="_blank" rel="noreferrer">MAV_CMD_DO_SET_ROI_LOCATION</a></li><li><a href="https://mavlink.io/en/messages/common.html#MAV_CMD_DO_SET_ROI_WPNEXT_OFFSET" target="_blank" rel="noreferrer">MAV_CMD_DO_SET_ROI_WPNEXT_OFFSET</a></li><li><a href="https://mavlink.io/en/messages/common.html#MAV_CMD_DO_SET_ROI_NONE" target="_blank" rel="noreferrer">MAV_CMD_DO_SET_ROI_NONE</a></li><li><a href="https://mavlink.io/en/messages/common.html#MAV_CMD_DO_CHANGE_SPEED" target="_blank" rel="noreferrer">MAV_CMD_DO_CHANGE_SPEED</a></li><li><a href="https://mavlink.io/en/messages/common.html#MAV_CMD_DO_SET_HOME" target="_blank" rel="noreferrer">MAV_CMD_DO_SET_HOME</a></li><li><a href="https://mavlink.io/en/messages/common.html#MAV_CMD_DO_SET_SERVO" target="_blank" rel="noreferrer">MAV_CMD_DO_SET_SERVO</a></li><li><a href="https://mavlink.io/en/messages/common.html#MAV_CMD_DO_LAND_START" target="_blank" rel="noreferrer">MAV_CMD_DO_LAND_START</a></li><li><a href="https://mavlink.io/en/messages/common.html#MAV_CMD_DO_TRIGGER_CONTROL" target="_blank" rel="noreferrer">MAV_CMD_DO_TRIGGER_CONTROL</a></li><li><a href="https://mavlink.io/en/messages/common.html#MAV_CMD_DO_DIGICAM_CONTROL" target="_blank" rel="noreferrer">MAV_CMD_DO_DIGICAM_CONTROL</a></li><li><a href="https://mavlink.io/en/messages/common.html#MAV_CMD_DO_MOUNT_CONFIGURE" target="_blank" rel="noreferrer">MAV_CMD_DO_MOUNT_CONFIGURE</a></li><li><a href="https://mavlink.io/en/messages/common.html#MAV_CMD_DO_MOUNT_CONTROL" target="_blank" rel="noreferrer">MAV_CMD_DO_MOUNT_CONTROL</a></li><li><a href="https://mavlink.io/en/messages/common.html#MAV_CMD_IMAGE_START_CAPTURE" target="_blank" rel="noreferrer">MAV_CMD_IMAGE_START_CAPTURE</a></li><li><a href="https://mavlink.io/en/messages/common.html#MAV_CMD_IMAGE_STOP_CAPTURE" target="_blank" rel="noreferrer">MAV_CMD_IMAGE_STOP_CAPTURE</a></li><li><a href="https://mavlink.io/en/messages/common.html#MAV_CMD_VIDEO_START_CAPTURE" target="_blank" rel="noreferrer">MAV_CMD_VIDEO_START_CAPTURE</a></li><li><a href="https://mavlink.io/en/messages/common.html#MAV_CMD_VIDEO_STOP_CAPTURE" target="_blank" rel="noreferrer">MAV_CMD_VIDEO_STOP_CAPTURE</a></li><li><a href="https://mavlink.io/en/messages/common.html#MAV_CMD_DO_SET_CAM_TRIGG_DIST" target="_blank" rel="noreferrer">MAV_CMD_DO_SET_CAM_TRIGG_DIST</a></li><li><a href="https://mavlink.io/en/messages/common.html#MAV_CMD_DO_SET_CAM_TRIGG_INTERVAL" target="_blank" rel="noreferrer">MAV_CMD_DO_SET_CAM_TRIGG_INTERVAL</a></li><li><a href="https://mavlink.io/en/messages/common.html#MAV_CMD_SET_CAMERA_MODE" target="_blank" rel="noreferrer">MAV_CMD_SET_CAMERA_MODE</a></li><li><a href="https://mavlink.io/en/messages/common.html#MAV_CMD_NAV_DELAY" target="_blank" rel="noreferrer">MAV_CMD_NAV_DELAY</a></li><li><a href="https://mavlink.io/en/messages/common.html#MAV_CMD_NAV_RETURN_TO_LAUNCH" target="_blank" rel="noreferrer">MAV_CMD_NAV_RETURN_TO_LAUNCH</a></li><li><a href="https://mavlink.io/en/messages/common.html#MAV_CMD_DO_CONTROL_VIDEO" target="_blank" rel="noreferrer">MAV_CMD_DO_CONTROL_VIDEO</a></li><li><a href="https://mavlink.io/en/messages/common.html#MAV_CMD_DO_GIMBAL_MANAGER_PITCHYAW" target="_blank" rel="noreferrer">MAV_CMD_DO_GIMBAL_MANAGER_PITCHYAW</a></li><li><a href="https://mavlink.io/en/messages/common.html#MAV_CMD_DO_GIMBAL_MANAGER_CONFIGURE" target="_blank" rel="noreferrer">MAV_CMD_DO_GIMBAL_MANAGER_CONFIGURE</a></li><li><a href="https://mavlink.io/en/messages/common.html#MAV_CMD_OBLIQUE_SURVEY" target="_blank" rel="noreferrer">MAV_CMD_OBLIQUE_SURVEY</a></li><li><a href="https://mavlink.io/en/messages/common.html#MAV_CMD_SET_CAMERA_ZOOM" target="_blank" rel="noreferrer">MAV_CMD_SET_CAMERA_ZOOM</a></li><li><a href="https://mavlink.io/en/messages/common.html#MAV_CMD_SET_CAMERA_FOCUS" target="_blank" rel="noreferrer">MAV_CMD_SET_CAMERA_FOCUS</a></li><li><a href="https://mavlink.io/en/messages/common.html#MAV_CMD_NAV_VTOL_TAKEOFF" target="_blank" rel="noreferrer">MAV_CMD_NAV_VTOL_TAKEOFF</a><ul><li><code>MAV_CMD_NAV_VTOL_TAKEOFF.param2</code> (заголовок переходу) ігнорується. Замість цього напрямок до наступної маршрутної точки використовується для переходу. </li></ul></li><li><a href="https://mavlink.io/en/messages/common.html#MAV_CMD_DO_AUTOTUNE_ENABLE" target="_blank" rel="noreferrer">MAV_CMD_DO_AUTOTUNE_ENABLE</a><ul><li>Disabling autotune by setting <code>param1</code> to zero is currently not supported. To abort autotune during a mission, switch to another flight mode.</li><li>Axis selection specified in the MAVLink message is ignored (<code>param2</code> must be set to 0) .</li></ul></li></ul><p>Визначення GeoFence</p><ul><li><a href="https://mavlink.io/en/messages/common.html#MAV_CMD_NAV_FENCE_RETURN_POINT" target="_blank" rel="noreferrer">MAV_CMD_NAV_FENCE_RETURN_POINT</a></li><li><a href="https://mavlink.io/en/messages/common.html#MAV_CMD_NAV_FENCE_POLYGON_VERTEX_INCLUSION" target="_blank" rel="noreferrer">MAV_CMD_NAV_FENCE_POLYGON_VERTEX_INCLUSION</a></li><li><a href="https://mavlink.io/en/messages/common.html#MAV_CMD_NAV_FENCE_POLYGON_VERTEX_EXCLUSION" target="_blank" rel="noreferrer">MAV_CMD_NAV_FENCE_POLYGON_VERTEX_EXCLUSION</a></li><li><a href="https://mavlink.io/en/messages/common.html#MAV_CMD_NAV_FENCE_CIRCLE_INCLUSION" target="_blank" rel="noreferrer">MAV_CMD_NAV_FENCE_CIRCLE_INCLUSION</a></li><li><a href="https://mavlink.io/en/messages/common.html#MAV_CMD_NAV_FENCE_CIRCLE_EXCLUSION" target="_blank" rel="noreferrer">MAV_CMD_NAV_FENCE_CIRCLE_EXCLUSION</a></li></ul><p>Точки збору</p><ul><li><a href="https://mavlink.io/en/messages/common.html#MAV_CMD_NAV_RALLY_POINT" target="_blank" rel="noreferrer">MAV_CMD_NAV_RALLY_POINT</a></li></ul><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Please add an issue report or PR if you find a missing/incorrect message.</p><ul><li>PX4 аналізує вищезазначені повідомлення, але на них не обов&#39;язково <em>реагує</em>. Наприклад, деякі повідомлення є специфічними для типу транспортного засобу.</li><li>PX4 не підтримує локальні координати для команд місій (наприклад, <a href="https://mavlink.io/en/messages/common.html#MAV_FRAME_LOCAL_NED" target="_blank" rel="noreferrer">MAV_FRAME_LOCAL_NED</a>).</li><li>Не всі повідомлення/команди доступні через <em>QGroundControl</em>.</li><li>Список може стати застарілим, оскільки додаються повідомлення. Ви можете перевірити поточний набір, оглянувши код. Підтримка - <code>MavlinkMissionManager::parse_mavlink_mission_item</code> у <a href="https://github.com/PX4/PX4-Autopilot/blob/main/src/modules/mavlink/mavlink_mission.cpp" target="_blank" rel="noreferrer">/src/modules/mavlink/mavlink_mission.cpp</a>.</li></ul></div><h2 id="mission-command-timeouts" tabindex="-1">Mission Command Timeouts <a class="header-anchor" href="#mission-command-timeouts" aria-label="Permalink to &quot;Mission Command Timeouts&quot;">​</a></h2><p>Some mission commands/items can take time to complete, such as a gripper opening and closing, a winch extending or retracting, or a gimbal moving to point at a region of interest.</p><p>Where provided PX4 may use sensor feedback from the hardware to determine when the action has completed and then move to the next mission item. If not provided, or if the feedback is lost, a mission command timeout can be used to ensure that these kinds of actions will progress to the next mission item rather than blocking progression.</p><p>The timeout is set using the <a href="./../advanced_config/parameter_reference#MIS_COMMAND_TOUT">MIS_COMMAND_TOUT</a> parameter. This should be set to be a small amount greater than the time required for the longest long-running action in the mission to complete.</p><h2 id="закруглені-повороти-траєкторія-міжточкового-маршруту" tabindex="-1">Закруглені повороти: Траєкторія міжточкового маршруту <a class="header-anchor" href="#закруглені-повороти-траєкторія-міжточкового-маршруту" aria-label="Permalink to &quot;Закруглені повороти: Траєкторія міжточкового маршруту&quot;">​</a></h2><p>PX4 очікує пряму лінію від попередньої точки маршруту до поточної цілі (він не планує будь-якого іншого шляху між точками маршруту - якщо вам потрібен такий, ви можете симулювати це додаванням додаткових точок маршруту).</p><p>Технічні засоби керування MC будуть змінювати <em>швидкість</em> при наближенні або виходженні з точки відповідно до налаштувань <a href="./../config_mc/mc_jerk_limited_type_trajectory#auto-mode">обмеження ривків</a>. Транспортний засіб буде слідувати плавною округлою кривою до наступної точки шляху (якщо визначено) визначеною радіусом прийняття (<a href="./../advanced_config/parameter_reference#NAV_ACC_RAD">NAV_ACC_RAD</a>). Діаграма нижче показує види шляхів, які ви можете очікувати.</p><p><img src="'+l+'" alt="acc-rad"></p><p>Транспортні засоби переключаються на наступну точку шляху, як тільки вони потрапляють в радіус прийняття (<a href="./../advanced_config/parameter_reference#NAV_ACC_RAD">NAV_ACC_RAD</a>).</p><h2 id="місія-зліт" tabindex="-1">Місія зліт <a class="header-anchor" href="#місія-зліт" aria-label="Permalink to &quot;Місія зліт&quot;">​</a></h2><p>Заплануйте місію зльоту мультикоптера, додавши елемент місії <code>TAKEOFF</code> на карту (це відповідає <a href="https://mavlink.io/en/messages/common.html#MAV_CMD_NAV_TAKEOFF" target="_blank" rel="noreferrer">MAV_CMD_NAV_TAKEOFF</a> команді MAVLink).</p><p>Під час виконання цієї місії транспортний засіб підніметься вертикально до мінімальної висоти взяття на озброєння, визначеної в параметрі <a href="./../advanced_config/parameter_reference#MIS_TAKEOFF_ALT">MIS_TAKEOFF_ALT</a>, а потім рушить у напрямку 3D-позиції, визначеної у елементі місії.</p><p>Якщо місія без виконання завдань стартує, транспортний засіб підійде на мінімальну висоту взльоту, а потім перейде до першого елементу місії <code>Waypoint</code>.</p><p>Якщо транспортний засіб вже знаходиться в повітрі під час початку місії, місія зльоту розглядається як звичайний точка шляху.</p><h2 id="дивіться-також" tabindex="-1">Дивіться також <a class="header-anchor" href="#дивіться-також" aria-label="Permalink to &quot;Дивіться також&quot;">​</a></h2><ul><li><a href="./../flying/missions">Місії</a><ul><li><a href="./../flying/package_delivery_mission">Місія доставки посилок</a></li></ul></li><li><a href="./../flight_modes_fw/mission">Режим Місії (FW)</a></li></ul>',27))])}const E=n(d,[["render",A]]);export{V as __pageData,E as default};
